mapper.select:
SELECT 
  FROM pay04_formula
       INNER JOIN pay20_item ON pay20_item_cd = pay04_item_cd
 WHERE pay04_company_id = #{companyId}
   AND pay04_start_date = #{startDate}

mapper.update:
UPDATE pay04_formula
   SET pay04_formula_form = #{req.formulaForm},
       pay04_note         = #{req.note}
 WHERE pay04_formula_id = #{req.formulaId}
   AND pay04_company_id = #{companyId}

mapper.delete:
DELETE FROM pay04_formula
 WHERE pay04_company_id = #{companyId}
   AND pay04_start_date = #{startDate}

DELETE FROM pay04_formula
 WHERE pay04_company_id = #{companyId}
   AND pay04_formula_id IN
#{id}
